// Hot batch 257: seventy- and seventy-one-instruction functions no route reaches, written by hand from `tools.disasm`
// and verified by synthetic cases (handle-guarded calls through temporaries, an augmentation-string parse,
// unaligned record copies, tree insertion, reference-count acquires and per-key table reads).
// No names: none has evidence.
#include "decomp_registry.hpp"
#include "gt/game/hot_common.hpp"
#include "guest_call.hpp"

